const D = { energy: .62, scale: 1, speed: 1, density: .55, contract: .6, hue: 20, x: .5, y: .5, style: 'em', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// Striated muscle at the ultrastructure, the sarcomere. Myofibrils stack across
// the frame, each a run of repeating contractile units read as the classic EM
// banding: dark Z-lines bounding every sarcomere, light I-bands of thin actin,
// the dark A-band of myosin overlap with its lighter H-zone and central M-line.
// The muscle works: an activation wave travels along the fibres on incommensurate
// rates, so the sliding-filament mechanism plays out -- Z-lines pull together, the
// I-bands and H-zone narrow while the A-band holds its width -- a perpetual
// contraction/relaxation that ripples and never re-phases. Offered as a grey
// transmission electron micrograph, polarised-light birefringence, Z-disc
// immunofluorescence, or a false-colour tension map.
// -----------------------------------------------------------------------------

const u = Math.min(width, height);
const sp = 0.25 + P.speed * 0.9;
const contractD = 0.15 + P.contract * 0.6;

const sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7 + 8.3) * 43758.5453; return s - Math.floor(s); };

const nFib = Math.round(6 + P.density * 12);
if (!S.fib || S.seedUsed !== P.seed || S.nU !== nFib) {
  S.seedUsed = P.seed; S.nU = nFib;
  S.fib = [];
  for (let k = 0; k < nFib; k++) S.fib.push({
    xoff: fr(k * 7 + 3),                 // striation misregistration
    hj: (fr(k * 11 + 4) - 0.5) * 24,
    wj: 0.9 + fr(k * 13 + 5) * 0.24,     // per-fibril sarcomere length jitter
    aph: fr(k * 17 + 6) * 6.283          // activation phase offset (fibre recruitment)
  });
}

const t = K.t;
const style = P.style;
const glow = 0.4 + P.energy * 1.3 + A.rms * 0.3;
const waveK = 1.5 + P.density * 2.5;
// activation field: travelling twitch on incommensurate rates (never re-phases)
function activ(xn, aph) {
  const ph = -xn * waveK * 6.2831853 + t * 1.3 * sp + aph;
  return 0.5 + 0.32 * Math.sin(ph) + 0.18 * Math.sin(ph * 0.61 + 1.3) + 0.1 * Math.sin(t * 0.7 * sp + aph * 1.7)
    + K.pulse * 0.12 + A.bass * 0.18;
}

let bgH, bgS, bgB, mode;
if (style === 'polarized') { bgH = 250; bgS = 45; bgB = 8; mode = 'polarized'; }
else if (style === 'fluor') { bgH = 235; bgS = 55; bgB = 8; mode = 'fluor'; }
else if (style === 'thermal') { bgH = 240; bgS = 40; bgB = 10; mode = 'thermal'; }
else { bgH = 32; bgS = 8; bgB = 60; mode = 'em'; }     // EM: light-grey field, dark bands
const pale = (mode === 'em');

push();
noStroke(); rectMode(CORNER);
fill(bgH, bgS, bgB); rect(0, 0, width, height);

const fibH = height / nFib;
const SLmax = u * 0.085 * P.scale;                       // relaxed sarcomere length
const Awc = 0.6;                                          // A-band fraction of SLmax (constant length)

if (mode === 'polarized' || mode === 'fluor' || mode === 'thermal') blendMode(ADD);

const econ = P.energy;                                    // EM contrast rides on energy
for (let f = 0; f < nFib; f++) {
  const fb = S.fib[f];
  const y0 = f * fibH;
  const hue = (P.hue + fb.hj + 360) % 360;
  const slm = SLmax * fb.wj;
  const Aw = Awc * slm;                                   // constant A-band width
  const ry = y0 + fibH * 0.08, rh = fibH * 0.84 + 0.6;
  // slow striation scroll (each fibril shears at its own rate) -> whole pattern translates
  const scrollX = (0.06 + fb.xoff * 0.05) * sp * t * u + 0.4 * u * fb.xoff * Math.sin(t * 0.11 * sp + fb.aph);
  let x = ((-scrollX) % slm) - slm * (1 + fb.xoff);
  let guard = 0;
  while (x < width + slm && guard < 90) {
    guard++;
    const xn = (x + slm * 0.5) / width;
    const act = Math.max(0, Math.min(1.3, activ(xn, fb.aph)));
    const sl = slm * (1 - contractD * act);                // sliding filament: sarcomere shortens
    const Iw = Math.max(sl * 0.02, (sl - Aw) * 0.5);        // I-band width shrinks
    const overlap = contractD * act * 0.5 * Aw;
    const Hw = Math.max(0, Aw - 2 * overlap);               // H-zone shrinks
    const zx = x, ax0 = x + Iw, hx0 = x + Iw + (Aw - Hw) * 0.5, mx = x + sl * 0.5;
    if (mode === 'em') { // dark bands on grey; contrast from energy
      const Ic = 60 + econ * 12, Ac = 30 - econ * 16, Hc = 44 - econ * 6, Zc = 16 - econ * 8;
      fill(hue, 6, Ic, 100); rect(zx, ry, Math.max(1, sl), rh);                    // light ground (I level)
      fill(hue, 8, Ac + 4, 100); rect(ax0, ry, Math.max(1, Aw), rh);               // A-band dark
      if (Hw > 1) { fill(hue, 6, Hc, 100); rect(hx0, ry, Hw, rh); }                // H-zone lighter
      fill(hue, 10, Zc + 12, 100); rect(mx - Math.max(0.6, sl * 0.006), ry, Math.max(1.2, sl * 0.012), rh);  // M-line
      fill(hue, 12, Zc, 100); rect(zx - Math.max(0.6, sl * 0.009), ry, Math.max(1.6, sl * 0.018), rh);       // Z-line
    } else if (mode === 'polarized') { // A-band birefringent bright, I dark
      const b = Math.min(100, (22 + act * 44) * glow);
      fill(hue, 55, b * 0.3, 70); rect(zx, ry, Math.max(1, sl), rh);
      fill((hue + 20) % 360, 60, b, 82); rect(ax0, ry, Math.max(1, Aw), rh);       // A-band glows
      if (Hw > 1) { fill(hue, 40, b * 0.5, 70); rect(hx0, ry, Hw, rh); }           // H darker
    } else if (mode === 'fluor') { // Z-discs + M-line labelled, thin bright lines
      fill(hue, 20, 12 * glow, 40); rect(zx, ry, Math.max(1, sl), rh);
      const zb = Math.min(100, (42 + act * 45) * glow);
      fill(hue, 65, zb, 88); rect(zx - Math.max(0.8, sl * 0.02), ry, Math.max(1.8, sl * 0.045), rh);         // Z-disc
      fill((hue + 130) % 360, 60, Math.min(100, zb * 0.85), 80); rect(mx - Math.max(0.7, sl * 0.012), ry, Math.max(1.4, sl * 0.026), rh);  // M-line
    } else { // thermal tension map
      const force = Math.min(1, overlap / (Aw * 0.5 + 1e-4) + act * 0.2);
      const hh = 40 - force * 40 + (1 - force) * 200;      // blue(low) -> red(high)
      fill((hh + 360) % 360, 70, Math.min(100, (30 + force * 55) * glow), 80); rect(ax0, ry, Math.max(1, Aw), rh);
      fill(210, 50, Math.min(100, 22 * glow), 60); rect(zx, ry, Math.max(1, sl), rh);
    }
    x += sl;
  }
  // fibril separation (sarcolemma gap + faint highlight) -> stacked relief
  noStroke();
  fill(pale ? 32 : bgH, pale ? 10 : bgS, pale ? 34 : 4, pale ? 70 : 60); rect(0, y0, width, Math.max(1, fibH * 0.05));
  fill(pale ? 32 : (P.hue % 360), pale ? 4 : 30, pale ? 82 : 30, pale ? 40 : 24); rect(0, y0 + fibH * 0.05, width, Math.max(0.8, fibH * 0.02));
}
if (mode === 'polarized' || mode === 'fluor' || mode === 'thermal') blendMode(BLEND);

// subtle vignette
noFill(); for (let vi = 0; vi < 4; vi++) { stroke(bgH, bgS, pale ? bgB * 0.5 : 0, 9); strokeWeight(u * (0.05 + vi * 0.02)); ellipse(width / 2, height / 2, width * (1.02 + vi * 0.03), height * (1.02 + vi * 0.03)); }
pop();

if (P.alpha < 100) { push(); noStroke(); rectMode(CORNER); fill(bgH, bgS, bgB, 100 - Math.max(0, Math.min(100, P.alpha))); rect(0, 0, width, height); pop(); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
